// ─────────────────────────────────────────────
// МҰҒАЛІМДЕР ИНДЕКСІ
// direction: 'SMART' | 'JUNIOR' | 'ALL'
// ─────────────────────────────────────────────
export function buildTeachersIndex(monthId, direction = 'ALL', extra = {}) {
  const map = {};

  const addFromSchedule = (days, dir) => {
    (days || []).forEach(({ day, type, stream, lessons }) => {
      (lessons || []).forEach(({ subject, stream: lessonStream, teachers }) => {
        (teachers || []).forEach(({ name, times }) => {
          if (!map[name]) map[name] = [];
          map[name].push({ day, type, subject, stream: lessonStream || stream, times, direction: dir });
        });
      });
    });
  };

  if (direction === 'SMART' || direction === 'ALL') {
    addFromSchedule(smartScheduleByMonth[monthId], 'SMART');
    addFromSchedule(smartAdditionalScheduleByMonth[monthId], 'SMART');
    addFromSchedule(extra.smart, 'SMART');
  }
  if (direction === 'JUNIOR' || direction === 'ALL') {
    addFromSchedule(juniorScheduleByMonth[monthId], 'JUNIOR');
    addFromSchedule(extra.junior, 'JUNIOR');
  }

  return map;
}
